// You do NOT edit this file. You attack it from the DevTools Console.
//
// Notice that this code is reasonably well written: it uses async/await,
// checks res.ok, validates the data with YOUR Mission 1 validator and
// renders with textContent. It is still defenseless against Mission 3. Why?

const refreshBtn = document.getElementById("refresh-btn");
const statusMsg = document.getElementById("status-msg");
const tbody = document.querySelector("#status-table tbody");
const rejectedEl = document.getElementById("rejected-count");
const lastUpdatedEl = document.getElementById("last-updated");

function showError(message) {
  statusMsg.textContent = message;
  statusMsg.className = "error";
}

function renderRows(services) {
  tbody.replaceChildren();
  for (const s of services) {
    const tr = document.createElement("tr");
    const cells = [s.name, s.status.toUpperCase(), s.online === true ? "ONLINE" : "OFFLINE", s.latencyMs + " ms"];
    cells.forEach((text, i) => {
      const td = document.createElement("td");
      td.textContent = text;
      if (i === 1) td.className = "status-" + s.status;
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  }
}

async function loadStatus(url) {
  refreshBtn.disabled = true;
  statusMsg.className = "";
  statusMsg.textContent = "Loading...";
  try {
    const res = await fetch(url);
    if (!res.ok) {
      showError("Service unavailable (HTTP " + res.status + "). Try again later.");
      return;
    }

    const report = parseStatusReport(await res.text());
    if (report === undefined) {
      showError("Complete Mission 1 first: parseStatusReport() is not implemented yet.");
      return;
    }
    if (report.error !== null) {
      showError("The status service returned an unreadable response.");
      return;
    }

    renderRows(report.services);
    rejectedEl.textContent = report.rejected;
    lastUpdatedEl.textContent = new Date().toLocaleTimeString();
    statusMsg.textContent = "Loaded " + report.services.length + " services.";
  } catch (err) {
    showError("Could not reach the status service.");
    console.error(err);
  } finally {
    refreshBtn.disabled = false;
  }
}

refreshBtn.addEventListener("click", () => loadStatus("/api/status"));
document.getElementById("simulate-error-btn")
  .addEventListener("click", () => loadStatus("/api/status?simulate=error"));
document.getElementById("simulate-garbage-btn")
  .addEventListener("click", () => loadStatus("/api/status?simulate=garbage"));
